```python
def divide(a, b):
    try:
        result = a / b
        return result
    except ZeroDivisionError:
        print("Cannot divide by zero!")
        return None  # or any other value to indicate failure

# Usage:
print(divide(10, 2))  # Outputs: 5.0
print(divide(10, 0))  # Outputs: Cannot divide by zero!
